 static int HookRename(EnvDTE.DTE d,int pid,string root){string file=Path.Combine(root,"hook-rename-"+Guid.NewGuid().ToString("N")+".cpp");File.WriteAllText(file,"int AuditValue = 1;\r\n");d.ItemOperations.OpenFile(file).Activate();Pump(200);var s=(EnvDTE.TextSelection)d.ActiveDocument.Selection;s.MoveToLineAndOffset(1,7,false);FocusEditor(d,pid,file);var rows=new List<object>();keyboardHook=(code,msg,ptr)=>{var result=CallNextHookEx(IntPtr.Zero,code,msg,ptr);if(code>=0){var k=(LowKey)Marshal.PtrToStructure(ptr,typeof(LowKey));if((k.flags&16)!=0&&new uint[]{16,18,82}.Contains(k.vk))rows.Add(new{vk=k.vk,k.flags,message=msg.ToInt64(),downstreamConsumed=result!=IntPtr.Zero});}return result;};var hook=SetWindowsHookEx(13,keyboardHook,GetModuleHandle(null),0);if(hook==IntPtr.Zero)throw new Exception("Hook installation failed "+Marshal.GetLastWin32Error());try{Keys(pid,new ushort[]{18,16,82});Pump(700);}finally{UnhookWindowsHookEx(hook);GC.KeepAlive(keyboardHook);}File.WriteAllText(Path.Combine(root,"rename-input-hook.json"),json.Serialize(rows));Console.WriteLine(json.Serialize(rows));Cleanup(pid);if(d.ActiveDocument!=null&&d.ActiveDocument.FullName==file)d.ActiveDocument.Close(EnvDTE.vsSaveChanges.vsSaveChangesNo);return 0;}
 static int RenameAlias(EnvDTE.DTE d,int pid,string root){var file=Path.Combine(root,"alias-"+Guid.NewGuid().ToString("N")+".cpp");File.WriteAllText(file,"int AuditValue = 1;\r\n");d.ItemOperations.OpenFile(file).Activate();Pump(150);((EnvDTE.TextSelection)d.ActiveDocument.Selection).MoveToLineAndOffset(1,7,false);FocusEditor(d,pid,file);var c=d.Commands.Item("{f9d77864-fac8-457e-bd4f-552715151b6c}",266);SaveBinding(c);var old=(object[])c.Bindings;var events=d.Events;var ce=events.CommandEvents;ce.BeforeExecute+=Before;try{c.Bindings=old.Select(x=>(object)EnglishBinding(x.ToString())).Concat(new object[]{"텍스트 편집기::Ctrl+Shift+F11"}).ToArray();observed.Clear();signatures.Clear();Keys(pid,new ushort[]{17,16,122});Pump(700);bool received=signatures.Contains("{f9d77864-fac8-457e-bd4f-552715151b6c}:266");File.WriteAllText(Path.Combine(root,"rename-alias.json"),json.Serialize(new{chord="Ctrl+Shift+F11",received,commands=observed.ToArray()}));Console.WriteLine("Rename alias received="+received);Cleanup(pid);}finally{ce.BeforeExecute-=Before;RestoreBindings();GC.KeepAlive(events);}return 0;}
